const API = 'http://waha:3000';
const KEY = 'minha_chave_123';
const CONFIRM_CHATS = ['555185670380@c.us', '5551985670380@c.us'];
const SESSION = 'default';

const item = $input.first().json;
const body = item.body || item;
const payload = body.payload || body;
const session = body.session || payload.session || SESSION;
const from = String(payload.from || '');
const fromMe = payload.fromMe === true;
const event = String(body.event || '');
const hoje = $now.setZone('America/Sao_Paulo').toFormat('dd/MM/yyyy');

function extrairTextoWaha_(p) {
  p = p || {};
  const d = p._data || {};
  const msg = d.message || {};
  const cand = [];
  if (typeof p.body === 'string') cand.push(p.body);
  else if (p.body && typeof p.body === 'object') {
    cand.push(p.body.text, p.body.caption, p.body.content);
  }
  cand.push(p.text, p.caption, msg.conversation);
  if (msg.extendedTextMessage) cand.push(msg.extendedTextMessage.text);
  if (msg.imageMessage) cand.push(msg.imageMessage.caption);
  if (d.body) cand.push(d.body);
  for (let i = 0; i < cand.length; i++) {
    const t = String(cand[i] || '').trim();
    if (t.length > 3) return t;
  }
  return '';
}

function acharGrupo(p, bodyWrap) {
  const campos = [
    p.chatId, p.to, p.from,
    bodyWrap && bodyWrap.chatId,
    p._data && p._data.key && p._data.key.remoteJid,
    p._data && p._data.id && p._data.id.remote,
  ];
  for (let i = 0; i < campos.length; i++) {
    const v = String(campos[i] || '');
    if (v.includes('@g.us')) return v;
  }
  return '';
}

function tipoObrigatorio(nome) {
  const n = String(nome || '').toLowerCase();
  if (/follow.?up|saldo.?gestech|gestech.*follow/i.test(n)) return 'misc';
  if (/serializados|controle.*hc|controle\s*serializados/i.test(n)) return 'modems';
  return '';
}

function ehPlanilha(ext, mime, nome) {
  if (['xlsx','xlsm','xls'].includes(ext)) return true;
  if (mime.includes('spreadsheet') || mime.includes('excel')) return true;
  if (/follow.?up|saldo.?gestech|serializados|controle.*hc|\.xls/i.test(nome)) return true;
  return false;
}

const grupoId = acharGrupo(payload, body);

// === RESGATE OFFLINE: quando o WAHA reconecta (status WORKING) dispara o resgate ===
const statusSessao = String(payload.status || (payload._data && payload._data.status) || body.status || '').toUpperCase();
if (/session\.?status|^status$/i.test(event)) {
  if (statusSessao === 'WORKING') {
    return [{ json: { disparaResgate: true, skip: true, motivo: 'WAHA reconectou (WORKING) -> resgate offline' } }];
  }
  return [{ json: { skip: true, motivo: 'status sessao: ' + (statusSessao || event) } }];
}

if (event && !/message/i.test(event)) {
  return [{ json: { skip: true, motivo: 'evento: ' + event, from: from, grupoId: grupoId } }];
}

const type = String(payload.type || payload._data?.type || '').toLowerCase();
const media = payload.media || payload._data?.media || {};
const filename = String(
  media.filename || payload._data?.filename || payload._data?.message?.documentMessage?.fileName || ''
).trim();
const mimetype = String(
  media.mimetype || media.mimeType || payload._data?.message?.documentMessage?.mimetype || ''
).toLowerCase();
const msgId = String(payload.id || payload._data?.id?.id || payload._data?.key?.id || '');
const hasMedia = payload.hasMedia === true || type.includes('document') || !!media.url || (!!msgId && type.includes('document'));
const obrigatorio = tipoObrigatorio(filename) || tipoObrigatorio(mimetype);

if (obrigatorio && !grupoId) {
  throw new Error('OBRIGATORIO bloqueado: planilha ' + obrigatorio + ' sem grupo @g.us — confira WAHA webhook');
}
if (!grupoId && !obrigatorio) {
  return [{ json: { skip: true, motivo: 'nao e grupo (@g.us)', from: from, grupoId: '' } }];
}

// === Aprende o ID do grupo para o resgate offline saber onde varrer ===
if (grupoId) {
  const sdg = $getWorkflowStaticData('global');
  if (!sdg.gruposVistos) sdg.gruposVistos = {};
  sdg.gruposVistos[grupoId] = Date.now();
}

if (msgId) {
  const sd = $getWorkflowStaticData('global');
  if (!sd.seenMsg) sd.seenMsg = {};
  if (sd.seenMsg[msgId]) {
    return [{ json: { skip: true, motivo: 'duplicado webhook', from: from, grupoId: grupoId, obrigatorio: obrigatorio } }];
  }
  sd.seenMsg[msgId] = Date.now();
  const keys = Object.keys(sd.seenMsg);
  if (keys.length > 400) {
    keys.sort(function (a, b) { return sd.seenMsg[a] - sd.seenMsg[b]; });
    keys.slice(0, keys.length - 250).forEach(function (k) { delete sd.seenMsg[k]; });
  }
}

const texto = extrairTextoWaha_(payload);
const pareceBaseTci = /serial\s*[:\s]|transfer[eê]ncias\s+para|(?:de|origem)\s*[:\s].*para|\bpara\s*[:\s]|\bDE\s+\S+\s+PARA\s+/i.test(texto);
if (texto.length > 8 && pareceBaseTci && grupoId) {
  return [{ json: {
    skip: false, tipo: 'basetci', session, from, fromMe, texto, grupoId, obrigatorio: '',
    materiaisId: '1W1K7OzbZejmSbEUnQxJ9u43phV0sHYNWkeW3KIbv0vM', confirmChat: CONFIRM_CHATS[0], confirmChats: CONFIRM_CHATS, apiKey: KEY,
  }}];
}

if (hasMedia && (media.url || msgId)) {
  let url = media.url ? String(media.url) : '';
  if (url && !url.startsWith('http')) url = API + url;
  if (!url && msgId) {
    url = API + '/api/' + session + '/files/' + encodeURIComponent(msgId);
  }
  const ext = (filename.split('.').pop() || '').toLowerCase();
  if (!ehPlanilha(ext, mimetype, filename)) {
    if (obrigatorio) {
      throw new Error('OBRIGATORIO ' + obrigatorio + ' rejeitado: anexo nao e planilha (' + (filename || type) + ')');
    }
    return [{ json: { skip: true, motivo: 'anexo nao e planilha: ' + (filename || type), from: from, grupoId: grupoId } }];
  }
  let tipo = obrigatorio || 'modems';
  if (!obrigatorio) {
    if (/follow.?up|saldo.?gestech|gestech.*follow/i.test(filename)) tipo = 'misc';
    else if (/serializados|controle.*hc/i.test(filename)) tipo = 'modems';
    else if (/follow.?up|saldo.?gestech/i.test(mimetype + ' ' + filename)) tipo = 'misc';
  }
  return [{ json: {
    skip: false,
    obrigatorio: obrigatorio || '',
    tipo,
    session,
    from,
    grupoId,
    filename,
    downloadUrl: url,
    msgId: msgId,
    hoje: hoje,
    materiaisId: '1W1K7OzbZejmSbEUnQxJ9u43phV0sHYNWkeW3KIbv0vM',
    confirmChat: CONFIRM_CHATS[0],
    confirmChats: CONFIRM_CHATS,
    apiKey: KEY,
  }}];
}

return [{ json: { skip: true, motivo: 'sem planilha nem texto BASE TCI (texto=' + texto.length + ' chars, grupo=' + (grupoId ? 'ok' : 'nao') + ')', from: from, grupoId: grupoId, type: type, filename: filename } }];

const XLSX = require('xlsx');
const meta = $('Filtrar Grupo WAHA').first().json;
const bin = $input.first().binary?.data;
if (!bin) throw new Error('Download vazio — confira WAHA e URL do anexo');

const buf = Buffer.from(bin.data, 'base64');
const wb = XLSX.read(buf, {
  type: 'buffer', cellFormula: false, cellHTML: false, cellStyles: false, sheetStubs: false,
});

let sheetName = wb.SheetNames.find(function (n) {
  return String(n).toUpperCase().indexOf('SALDO GESTECH') >= 0;
});
if (!sheetName) {
  throw new Error('Aba SALDO GESTECH nao encontrada. Abas: ' + wb.SheetNames.join(' | '));
}

const rows = XLSX.utils.sheet_to_json(wb.Sheets[sheetName], { defval: '', raw: false });

function pick(row, aliases) {
  const norm = {};
  Object.keys(row).forEach(function (k) {
    norm[String(k).toLowerCase().replace(/\s+/g, ' ').trim()] = row[k];
  });
  for (let i = 0; i < aliases.length; i++) {
    const v = norm[aliases[i].toLowerCase()];
    if (v !== undefined && v !== '') return v;
  }
  return '';
}

const header = [
  'CodArmazem','Armazem','CodMaterial','Material',
  'Grupo Material','Agregador','Sub Grupo Agregador','Segmento','Subsegmento','Saldo'
];
const dataRows = [];

rows.forEach(function (row) {
  let tt = String(pick(row, ['codarmazem','cod armazem','tt'])).trim().toUpperCase();
  if (!tt.startsWith('TT')) return;
  const saldoRaw = pick(row, ['saldo']);
  const saldo = Number(String(saldoRaw).replace(/\./g, '').replace(',', '.')) || Number(saldoRaw) || 0;
  if (saldo <= 0) return;
  dataRows.push([
    tt,
    pick(row, ['armazem']),
    pick(row, ['codmaterial','cod material']),
    pick(row, ['material']),
    pick(row, ['grupo material']),
    pick(row, ['agregador']),
    pick(row, ['sub grupo agregador','subsegmento']),
    pick(row, ['segmento','segmento2','_segmento']),
    pick(row, ['subsegmento','_subsegmento']),
    saldo,
  ]);
});

if (!dataRows.length) {
  if (meta.obrigatorio === 'misc') throw new Error('OBRIGATORIO misc: SALDO GESTECH sem linhas TT');
  throw new Error('SALDO GESTECH: nenhuma linha TT com saldo > 0');
}

return [{
  json: {
    sheetName: 'BASE MICELANEAS',
    documentId: meta.materiaisId,
    filename: meta.filename,
    tipo: 'misc',
    total: dataRows.length,
    header: header,
    rows: dataRows,
    confirmChat: meta.confirmChat,
    apiKey: meta.apiKey,
    session: meta.session,
  }
}];

const XLSX = require('xlsx');
const meta = $('Filtrar Grupo WAHA').first().json;
const bin = $input.first().binary?.data;
if (!bin) throw new Error('Download vazio');

const buf = Buffer.from(bin.data, 'base64');
const wb = XLSX.read(buf, {
  type: 'buffer', cellFormula: false, cellHTML: false, cellStyles: false, sheetStubs: false,
});

let sheetName = wb.SheetNames.find(function (n) {
  return String(n).toUpperCase() === 'GESTECH';
});
if (!sheetName) {
  sheetName = wb.SheetNames.find(function (n) {
    return String(n).toUpperCase().indexOf('BASE SERIALIZADOS') >= 0;
  });
}
if (!sheetName) throw new Error('Aba GESTECH / BASE SERIALIZADOS nao encontrada');

const rows = XLSX.utils.sheet_to_json(wb.Sheets[sheetName], { defval: '', raw: false });
const isBase = String(sheetName).toUpperCase().indexOf('BASE SERIALIZADOS') >= 0;

function pick(row, aliases) {
  const norm = {};
  Object.keys(row).forEach(function (k) {
    norm[String(k).toLowerCase().replace(/\s+/g, ' ').trim()] = row[k];
  });
  for (let i = 0; i < aliases.length; i++) {
    const v = norm[aliases[i].toLowerCase()];
    if (v !== undefined && v !== '') return v;
  }
  return '';
}

const header = ['Serial','Gestech','Material','Velocidade'];
const dataRows = [];

rows.forEach(function (row) {
  const serial = String(
    pick(row, isBase ? ['n de serie','numero de serie','serial'] : ['serial'])
  ).trim().toUpperCase();
  let tt = String(pick(row, isBase ? ['gestech'] : ['codarm','armazem','gestech','matricula'])).trim().toUpperCase();
  if (!serial || !tt.startsWith('TT')) return;
  const material = pick(row, isBase ? ['texto breve material','material'] : ['material']);
  const vel = pick(row, ['velocidade','texto breve material','material']);
  dataRows.push([serial, tt, material, vel]);
});

if (!dataRows.length) {
  if (meta.obrigatorio === 'modems') throw new Error('OBRIGATORIO modems: GESTECH sem serial TT');
  throw new Error('Modems: nenhum serial TT valido');
}

return [{
  json: {
    sheetName: 'ALMOX SERIALIZADA',
    documentId: meta.materiaisId,
    filename: meta.filename,
    tipo: 'modems',
    total: dataRows.length,
    header: header,
    rows: dataRows,
    confirmChat: meta.confirmChat,
    apiKey: meta.apiKey,
    session: meta.session,
  }
}];

const meta = $('Filtrar Grupo WAHA').first().json;
const t = String(meta.texto || '').replace(/\r/g, '');
const linhas = t.split(/\n+/).map(function (l) { return l.trim(); }).filter(Boolean);

function pareceSerial(s) {
  const u = String(s || '').trim().toUpperCase().replace(/[\s-]/g, '');
  if (u.length < 8 || u.length > 24) return false;
  if (/^\d+$/.test(u)) return false;
  if (!/[0-9]/.test(u) || !/[A-Z]/.test(u)) return false;
  return /^[A-Z0-9]+$/.test(u);
}

function parseCabecalho(l) {
  let m = l.match(/^DE\s+(.+?)\s+PARA\s+(.+)$/i);
  if (m) return { de: m[1].trim(), para: m[2].trim() };
  m = l.match(/(?:de|origem)\s*[:\s]+(.+?)\s+para\s*[:\s]+(.+)/i);
  if (m) return { de: m[1].trim(), para: m[2].trim() };
  return null;
}

function extrairTt(s) {
  const m = String(s || '').match(/\b(TT\d+)\b/i);
  return m ? m[1].toUpperCase() : '';
}

function limparNome(s) {
  return String(s || '').replace(/\bTT\d+\b/gi, '').replace(/\s+/g, ' ').trim();
}

/** Gestech: "Transferencias para" + TT + nome + Serial: XXX [OK] */
function parseTransferenciasPara_(texto, linhas) {
  if (!/transfer[eê]ncias\s+para/i.test(texto)) return [];
  let ttCol = '';
  let para = '';
  for (let i = 0; i < linhas.length; i++) {
    const l = linhas[i];
    if (/transfer[eê]ncias\s+para/i.test(l)) continue;
    const ttLinha = l.match(/^\s*(TT\d+)\s*$/i);
    if (ttLinha && !ttCol) {
      ttCol = ttLinha[1].toUpperCase();
      continue;
    }
    if (ttCol && !para && !/serial|material|unidades|transfer|prazo|cancelad|^\d/i.test(l)) {
      if (l.length > 4 && /[A-Za-z]/.test(l)) {
        para = limparNome(l);
        continue;
      }
    }
  }
  if (!ttCol && !para) return [];
  const rows = [];
  const reSerial = /serial\s*[:\s]+([A-Z0-9]{8,24})(?:\s+(OK))?/gi;
  let m;
  while ((m = reSerial.exec(texto)) !== null) {
    const serial = m[1].toUpperCase();
    const recebido = !!(m[2] && /^OK/i.test(String(m[2]).trim()));
    const obs = recebido ? 'TÉCNICO' : 'PENDENCIA DE TRANSFERENCIA';
    rows.push(['', '', '', serial, '', para, ttCol || 'OK', '', obs]);
  }
  return rows;
}

const rows = [];
let obsPadrao = 'PENDENCIA DE TRANSFERENCIA';
let de = '';
let para = '';
let ttCol = '';

const gestechRows = parseTransferenciasPara_(t, linhas);
if (gestechRows.length) {
  rows.push.apply(rows, gestechRows);
}

for (let i = 0; i < linhas.length; i++) {
  const cab = parseCabecalho(linhas[i]);
  if (cab) {
    de = limparNome(cab.de);
    para = limparNome(cab.para);
    ttCol = extrairTt(cab.para) || extrairTt(cab.de) || ttCol;
    continue;
  }
  if (/^obs\s*[:\s]/i.test(linhas[i])) {
    obsPadrao = linhas[i].replace(/^obs\s*[:\s]*/i, '').trim() || obsPadrao;
    continue;
  }
  const mSerialLinha = linhas[i].match(/^serial\s*[:\s]+([A-Z0-9]{8,24})(?:\s+(OK))?\s*$/i);
  if (mSerialLinha && (de || para)) {
    const serial = mSerialLinha[1].toUpperCase();
    const obs = mSerialLinha[2] ? 'TÉCNICO' : obsPadrao;
    rows.push(['', '', '', serial, de, para, ttCol || 'OK', '', obs]);
    continue;
  }
  if (pareceSerial(linhas[i])) {
    if (!de && !para) continue;
    const serial = linhas[i].toUpperCase().replace(/[\s-]/g, '');
    rows.push(['', '', '', serial, de, para, ttCol || 'OK', '', obsPadrao]);
  }
}

if (!rows.length) {
  function extrair(re, idx) {
    const m = t.match(re);
    return m && m[idx] ? String(m[idx]).trim() : '';
  }
  const serial = extrair(/serial[:\s]+([A-Z0-9]+)/i, 1);
  de = extrair(/(?:de|origem)[:\s]+(.+?)(?:\n|para|$)/i, 1);
  para = extrair(/para[:\s]+(.+?)(?:\n|$)/i, 1);
  ttCol = extrairTt(para) || extrairTt(de);
  para = limparNome(para);
  de = limparNome(de);
  const obs = extrair(/obs[:\s]+(.+)/i, 1) || (t.toUpperCase().indexOf('PENDENTE') >= 0 ? obsPadrao : t.substring(0, 120));
  if (serial && (de || para)) {
    rows.push(['', '', '', serial.toUpperCase(), de, para, ttCol || 'OK', '', obs]);
  }
}

if (!rows.length) {
  throw new Error('Texto BASE TCI nao reconhecido (use DE X PARA Y TT... + seriais, um por linha)');
}

const hoje = $now.setZone('America/Sao_Paulo').toFormat('dd/MM/yyyy');
rows.forEach(function (r) { if (!r[7]) r[7] = hoje; });

return [{
  json: {
    sheetName: 'BASE TCI',
    documentId: meta.materiaisId,
    tipo: 'basetci',
    appendMode: true,
    rows: rows,
    confirmChat: meta.confirmChat,
    apiKey: meta.apiKey,
    session: meta.session,
    total: rows.length,
  }
}];

const item = $input.first().json;
const meta = $('Filtrar Grupo WAHA').first().json;
const header = item.header || [];
const rows = item.rows || [];
if (!rows.length) {
  if (meta.obrigatorio) {
    throw new Error('OBRIGATORIO ' + meta.obrigatorio + ' falhou: zero linhas para gravar');
  }
  throw new Error('Sem linhas para gravar');
}
const appendMode = item.appendMode === true || item.tipo === 'basetci';
const values = appendMode ? rows : [header].concat(rows);
const hoje = $now.setZone('America/Sao_Paulo').toFormat('dd/MM/yyyy HH:mm');
const obr = meta.obrigatorio || '';
const rotulo = obr === 'misc' ? 'FOLLOW UP → BASE MICELANEAS' : (obr === 'modems' ? 'SERIALIZADOS → ALMOX' : item.sheetName);
const prefix = obr ? '🚨 OBRIGATÓRIO DO DIA — ' : '✅ ';
const det = appendMode ? ' (append, sem apagar historico)' : '';
const msg = prefix + rotulo + det + '\n' + item.sheetName + ': ' + rows.length + ' linha(s)\nArquivo: ' + (item.filename || meta.filename || 'texto grupo') + '\n' + hoje;
return [{
  json: {
    documentId: item.documentId,
    sheetName: item.sheetName,
    values: values,
    appendMode: appendMode,
    rowCount: rows.length,
    msg: msg,
    obrigatorio: obr,
    confirmChat: meta.confirmChat,
    confirmChats: meta.confirmChats || [meta.confirmChat],
    apiKey: item.apiKey || meta.apiKey,
    session: item.session || meta.session || 'default',
  }
}];

const prep = $('Preparar MATERIAIS').first().json;
const meta = $('Filtrar Grupo WAHA').first().json;
const hojeKey = $now.setZone('America/Sao_Paulo').toFormat('dd/MM/yyyy');
const sd = $getWorkflowStaticData('global');
if (!sd.obrigatorioDia) sd.obrigatorioDia = {};
if (!sd.obrigatorioDia[hojeKey]) sd.obrigatorioDia[hojeKey] = {};
const chave = prep.obrigatorio || meta.obrigatorio;
if (chave === 'misc' || chave === 'modems') {
  sd.obrigatorioDia[hojeKey][chave] = {
    ok: true,
    linhas: prep.rowCount,
    aba: prep.sheetName,
    arquivo: meta.filename || '',
    hora: $now.setZone('America/Sao_Paulo').toFormat('HH:mm'),
  };
}
const keys = Object.keys(sd.obrigatorioDia);
if (keys.length > 14) {
  keys.sort();
  keys.slice(0, keys.length - 10).forEach(function (k) { delete sd.obrigatorioDia[k]; });
}
return [{ json: { ok: true, dia: hojeKey, registro: sd.obrigatorioDia[hojeKey] } }];

// === RESGATE OFFLINE ===
// Roda a cada 10 min E quando o WAHA reconecta (status WORKING).
// Le o historico recente de cada grupo conhecido e re-injeta as mensagens
// no proprio webhook do fluxo. O dedup (seenMsg) do "Filtrar Grupo WAHA"
// garante que nada seja gravado em duplicidade.
return (async () => {
  const API = 'http://waha:3000';
  const KEY = 'minha_chave_123';
  const SESSION = 'default';
  const N8N_WEBHOOK = 'http://localhost:5678/webhook/painel-carga-waha';
  const GRUPOS_FIXOS = []; // opcional: ['120363XXXXXXXX@g.us']
  const LIMIT = 100;

  const sd = $getWorkflowStaticData('global');
  let grupos = GRUPOS_FIXOS.length ? GRUPOS_FIXOS.slice() : Object.keys(sd.gruposVistos || {});

  // Fallback: tenta descobrir grupos pela API se ainda nao aprendeu nenhum ao vivo
  if (!grupos.length) {
    try {
      const gs = await this.helpers.httpRequest({
        method: 'GET',
        url: API + '/api/' + SESSION + '/groups',
        headers: { 'X-Api-Key': KEY },
        json: true,
      });
      (gs || []).forEach(function (g) {
        const id = g && g.id ? (g.id._serialized || g.id) : '';
        if (String(id).includes('@g.us')) grupos.push(String(id));
      });
    } catch (e) {}
  }

  if (!grupos.length) {
    return [{ json: { resgate: true, ok: false, motivo: 'nenhum grupo conhecido ainda — envie 1 mensagem no grupo para o fluxo aprender o ID' } }];
  }

  const overlap = 15 * 60 * 1000;
  const desde = (sd.ultimoResgate || (Date.now() - 24 * 60 * 60 * 1000)) - overlap;

  let lidas = 0;
  let reinjetadas = 0;
  const erros = [];

  for (let gi = 0; gi < grupos.length; gi++) {
    const g = grupos[gi];
    let msgs = [];
    try {
      msgs = await this.helpers.httpRequest({
        method: 'GET',
        url: API + '/api/' + SESSION + '/chats/' + encodeURIComponent(g) + '/messages?limit=' + LIMIT + '&downloadMedia=true',
        headers: { 'X-Api-Key': KEY },
        json: true,
      });
    } catch (e) {
      erros.push('GET ' + g + ': ' + (e.message || String(e)));
      continue;
    }
    if (!Array.isArray(msgs)) msgs = (msgs && msgs.messages) || [];

    for (let mi = 0; mi < msgs.length; mi++) {
      const m = msgs[mi];
      lidas++;
      const ts = Number(m.timestamp || (m._data && m._data.t) || 0) * 1000;
      if (ts && ts < desde) continue;
      const envelope = { event: 'message.any', session: SESSION, payload: m };
      try {
        await this.helpers.httpRequest({
          method: 'POST',
          url: N8N_WEBHOOK,
          headers: { 'Content-Type': 'application/json' },
          body: envelope,
          json: true,
        });
        reinjetadas++;
      } catch (e) {
        erros.push('POST ' + g + ': ' + (e.message || String(e)));
      }
    }
  }

  sd.ultimoResgate = Date.now();
  return [{ json: {
    resgate: true,
    ok: true,
    grupos: grupos.length,
    lidas: lidas,
    reinjetadas: reinjetadas,
    erros: erros,
    ultimoResgate: new Date(sd.ultimoResgate).toISOString(),
  }}];
})();
